-- KHALIS EXPORT PORTAL — CURRENT EXCEL PRICE LIST SYNC
-- Generated from: KHALIS EXPORT PRICE LIST EXCEL.xlsx
-- Safe sync:
--   * Does NOT delete products.
--   * Updates products by barcode.
--   * Inserts new barcodes.
--   * Updates catalogue_unit_prices (USD/AED; confidential/staff-only).
--   * Updates public catalogue carton specs.
--   * Rebuilds collection links for barcodes present in this Excel.
--   * Products listed only under "NO STOCK" are kept in the DB but set DRAFT
--     so they do not appear on the public website.
--
-- IMPORTANT:
--   1) Run this only after Phase 3 migration 0003_catalogue_phase3.sql exists.
--   2) The enum value VERIFIED_FROM_CATALOGUE must already be committed.
--   3) Take a Supabase backup before a large production data sync.
--
-- This script intentionally does NOT retire the 74 old catalogue barcodes
-- missing from this Excel. An OPTIONAL retirement query is provided at the end.
BEGIN;

CREATE TEMP TABLE _khalis_excel_sync (
  barcode text PRIMARY KEY,
  name text NOT NULL,
  inspiration text,
  top_notes text,
  middle_notes text,
  base_notes text,
  pack_size numeric,
  pack_unit text NOT NULL,
  units_per_carton integer,
  carton_cbm numeric,
  carton_gross_weight_kg numeric,
  price_usd numeric,
  price_aed numeric,
  collection_name text,
  collection_slug text,
  is_public_catalogue boolean NOT NULL
) ON COMMIT DROP;


Woody, Musky', 'DEHNAL OUD HINDI', 'INDIAN SANDALWOOD, CEDARWOOD, VIRGINIA', 'VANILLA, WHITE MUSK', 'INDONASIAN DHANUL OUDH', 20, 'ML', 96, 0.16, 33.3, 6, 22, 'CONCENTRATED PERFUME OIL', 'concentrated-perfume-oil', TRUE);
Oriental Rose', 'MERAJ/AL HARAMIAN', 'SAFFRON, CLOVE', 'GERANIUM, ROSE, NAGAMOTHA', 'SANDALWOOD, MUSK', 18, 'ML', 96, 0.16, 33.3, 6, 22, 'CONCENTRATED PERFUME OIL', 'concentrated-perfume-oil', TRUE);
Ambery, Woody', 'KHALIS CREATION', 'CINNAMON, SAFFRON', 'CEDARWOOD, LAVENDER WOODY', 'AMBERY, MOSSY, SANDALWOOD, COCONUT', 20, 'ML', 96, 0.16, 36.1, 6, 22, 'CONCENTRATED PERFUME OIL', 'concentrated-perfume-oil', TRUE);
/PENHALIGONS', 'Raspberry, Citron and Bergamot', 'Raspberry, Citron and Bergamot', 'Patchouli and Clearwood', 100, 'ML', NULL, NULL, NULL, 15, 55, 'NEW NICHE COLLECTIONS', 'new-niche-collections', TRUE);
/LANCOME', 'Honey, Apple, Fruity Notes', 'Rose, Vanilla, Woody Notes', 'Amber Notes, Vanilla, Patchouli', 100, 'ML', NULL, NULL, NULL, 10, 37, 'NEW KHALIS COLLECTIONS', 'new-khalis-collections', TRUE);

-- 1) Ensure the current Excel's real public catalogue sections exist.
-- "NO STOCK" is deliberately not created as a public collection.
SELECT DISTINCT collection_name, collection_slug, 'official_khalis_excel_price_list'
FROM _khalis_excel_sync
WHERE is_public_catalogue
ON CONFLICT (slug) DO UPDATE
SET name = EXCLUDED.name,
    source = EXCLUDED.source,
    updated_at = now();

-- 2) Upsert products by the catalogue barcode.
-- Existing slugs are preserved; new products get a stable barcode-suffixed slug.
  barcode, slug, name, inspiration, top_notes, middle_notes, base_notes,
  pack_size, pack_unit, volume_ml, image_status,
  catalogue_status, status
)
SELECT
  barcode,
  lower(regexp_replace(
    regexp_replace(name, '[^a-zA-Z0-9]+', '-', 'g'),
    '(^-|-$)', '', 'g'
  )) || '-' || barcode,
  barcode, name, inspiration, top_notes, middle_notes, base_notes,
  pack_size, pack_unit,
  CASE WHEN pack_unit = 'ML' THEN round(pack_size)::integer ELSE NULL END,
  'PENDING',
  'VERIFIED_FROM_CATALOGUE'::verification_status,
  CASE WHEN is_public_catalogue THEN 'PUBLISHED'::product_status
       ELSE 'DRAFT'::product_status END
FROM _khalis_excel_sync
ON CONFLICT (barcode) WHERE barcode IS NOT NULL
DO UPDATE SET
  name = EXCLUDED.name,
  inspiration = EXCLUDED.inspiration,
  top_notes = EXCLUDED.top_notes,
  middle_notes = EXCLUDED.middle_notes,
  base_notes = EXCLUDED.base_notes,
  pack_size = EXCLUDED.pack_size,
  pack_unit = EXCLUDED.pack_unit,
  volume_ml = EXCLUDED.volume_ml,
  catalogue_status = EXCLUDED.catalogue_status,
  status = EXCLUDED.status,
  updated_at = now();

-- 3) Rebuild collection membership for the barcodes represented by this Excel.
-- This removes stale collection links for these products, then adds the
-- current public catalogue section links.
DELETE FROM collections_products cp
USING products p
WHERE cp.product_id = p.id
  AND p.barcode IN (SELECT barcode FROM _khalis_excel_sync);

SELECT c.id, p.id
FROM _khalis_excel_sync x
JOIN products p ON p.barcode = x.barcode
JOIN collections c ON c.slug = x.collection_slug
WHERE x.is_public_catalogue
ON CONFLICT (collection_id, product_id) DO NOTHING;

-- 4) Public carton/logistics values from the Excel.
-- The Excel gives a single carton weight field; it is stored as gross weight.
  product_id, units_per_carton, carton_cbm,
  carton_gross_weight_kg, verification_status
)
SELECT
  p.id, x.units_per_carton, x.carton_cbm,
  x.carton_gross_weight_kg,
  'VERIFIED_FROM_CATALOGUE'::verification_status
FROM _khalis_excel_sync x
JOIN products p ON p.barcode = x.barcode
ON CONFLICT (product_id) DO UPDATE SET
  units_per_carton = EXCLUDED.units_per_carton,
  carton_cbm = EXCLUDED.carton_cbm,
  carton_gross_weight_kg = EXCLUDED.carton_gross_weight_kg,
  verification_status = EXCLUDED.verification_status,
  updated_at = now();

-- 5) Confidential USD/AED unit pricing.
-- No public policy is added; existing Phase 3 RLS remains in force.
  product_id, price_usd, price_aed, source_page, verification_status
)
SELECT
  p.id, x.price_usd, x.price_aed, NULL,
  'VERIFIED_FROM_CATALOGUE'::verification_status
FROM _khalis_excel_sync x
JOIN products p ON p.barcode = x.barcode
ON CONFLICT (product_id) DO UPDATE SET
  price_usd = EXCLUDED.price_usd,
  price_aed = EXCLUDED.price_aed,
  verification_status = EXCLUDED.verification_status,
  updated_at = now();

-- 6) Safety checks before commit.
DO $$
DECLARE
  v_rows integer;
  v_public integer;
  v_no_stock integer;
  v_products integer;
  v_prices integer;
BEGIN
  SELECT count(*) INTO v_rows FROM _khalis_excel_sync;
  SELECT count(*) INTO v_public FROM _khalis_excel_sync WHERE is_public_catalogue;
  SELECT count(*) INTO v_no_stock FROM _khalis_excel_sync WHERE NOT is_public_catalogue;
  SELECT count(*) INTO v_products
    FROM products p
    WHERE p.barcode IN (SELECT barcode FROM _khalis_excel_sync);
  SELECT count(*) INTO v_prices
    FROM catalogue_unit_prices u
    JOIN products p ON p.id = u.product_id
    WHERE p.barcode IN (SELECT barcode FROM _khalis_excel_sync);

  IF v_rows <> 546 THEN
    RAISE EXCEPTION 'Safety check failed: expected 546 unique Excel barcodes, got %', v_rows;
  END IF;
  IF v_products <> 546 THEN
    RAISE EXCEPTION 'Safety check failed: expected 546 products after sync, got %', v_products;
  END IF;
  IF v_prices <> 546 THEN
    RAISE EXCEPTION 'Safety check failed: expected 546 price rows after sync, got %', v_prices;
  END IF;

  RAISE NOTICE 'Khalis Excel sync OK: % unique barcodes, % public, % no-stock.', v_rows, v_public, v_no_stock;
END $$;

COMMIT;

